def find(name):
    hits = sorted({p for prefix in ('', '*/', '*/*/', '*/*/*/') for p in Path('/kaggle/input').glob(prefix + name)})
    assert len(hits) == 1, (name, hits)
    return hits[0]
assert torch.cuda.device_count() == 2 and all(torch.cuda.get_device_name(i) == 'Tesla T4' for i in range(2))
